// Attempting to represent SQL queries as a verbose hierarchy of in-memory Criteria structures
struct Criteria {
    field: String,
    operator: String,
    value: String,
}

struct QueryObject {
    table: String,
    criteria: Vec<Criteria>,
}

impl QueryObject {
    fn add_criteria(&mut self, criteria: Criteria) {
        self.criteria.push(criteria);
    }

    fn generate_sql(&self) -> String {
        let mut sql = format!("SELECT * FROM {} WHERE ", self.table);
        let clauses: Vec<String> = self.criteria.iter()
            .map(|c| format!("{} {} '{}'", c.field, c.operator, c.value))
            .collect();
        sql.push_str(&clauses.join(" AND "));
        sql
    }
}
